let mut consumer = channel
    .basic_consume(queue, "consumer", BasicConsumeOptions::default(), FieldTable::default())
    .await?;
while let Some(delivery) = consumer.next().await {
    let delivery = delivery?;            // pushed by the connection executor
    match handle(&delivery.data).await {
        Ok(()) => delivery.ack(BasicAckOptions::default()).await?,
        Err(_) => delivery.nack(BasicNackOptions { requeue: false, ..Default::default() }).await?,
    }
}
